var i=`0867-chapli-kebab`;var s=`world-0867`;var t=`PK`;var a=`south-asia`;var o=4;var r=45;var d={en:`Chapli Kebab`,ua:`Чаплі-кебаб`};var l={en:`Chapli Kebab is a Pakistan dish made with ground beef, red onion, tomato, pomegranate seeds (dried). This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Чаплі-кебаб, страва кухні країни Пакистан. Основні складники: яловичий фарш, червона цибуля, помідор, сушені зерна граната. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-beef`,740,`g`],[`red-onion`,170,`g`],[`tomato`,180,`g`],[`coriander-seeds`,6,`g`],[`pomegranate-seeds-dried`,15,`g`],[`serrano-pepper`,2,`pcs`],[`table-salt`,null,`to_taste`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`canola-oil`,90,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon`,1,`pcs`],[`cilantro`,17,`g`]]}];var h={slug:i,id:s,country:`PK`,region:a,servings:4,minutes:45,title:d,text:l,steps:g};export{t as country,h as default,s as id,r as minutes,a as region,o as servings,i as slug,g as steps,l as text,d as title};